const items = $input.all();
const out = items.map(item => {
  const src = item.json.output || {};
  const o = { ...src };

  // Normalize time to strict 24-hour HH:mm (handles '10:00 AM', '10:00', '22:15', etc.)
  let t = String(o.time || '').trim();
  if (t) {
    let dt = DateTime.fromFormat(t, 'h:mm a', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'hh:mm a', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'H:mm', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'HH:mm', { zone: 'Asia/Dhaka' });
    o.time = dt.isValid ? dt.toFormat('HH:mm') : '09:00';
  } else {
    o.time = o.type === 'event' ? '09:00' : '';
  }

  o.priority = String(o.priority || 'normal').toLowerCase();
  if (!o.duration_minutes || o.duration_minutes <= 0) o.duration_minutes = 60;

  return { json: { output: o } };
});
return out;

const o = $json.output;
return [{ json: {
  title: o.title,
  date: o.date,
  time: o.time,
  duration_minutes: o.duration_minutes,
  description: o.description,
  location_or_link: o.location_or_link,
  chatId: $('Telegram Trigger').item.json.message.chat.id
} }];

const msg = $json.message;
const replyText = (msg.text || '').trim();
const origText = (msg.reply_to_message && msg.reply_to_message.text) || '';
const marker = 'AURORA-REF:';
const idx = origText.indexOf(marker);
let pending = {};
if (idx !== -1) {
  const b64 = origText.slice(idx + marker.length).trim();
  try {
    const jsonStr = Buffer.from(b64, 'base64').toString('utf-8');
    pending = JSON.parse(jsonStr);
  } catch (e) { pending = {}; }
}
return [{ json: { ...pending, replyText, chatId: msg.chat.id } }];

const pending = $('Parse Pending Event').item.json;
const parsed = $json.output || {};
let t = String(parsed.time || '').trim();
let dt = null;
if (t) {
  dt = DateTime.fromFormat(t, 'H:mm', { zone: 'Asia/Dhaka' });
  if (!dt.isValid) dt = DateTime.fromFormat(t, 'HH:mm', { zone: 'Asia/Dhaka' });
  if (!dt.isValid) dt = DateTime.fromFormat(t, 'h:mm a', { zone: 'Asia/Dhaka' });
  if (!dt.isValid) dt = DateTime.fromFormat(t, 'hh:mm a', { zone: 'Asia/Dhaka' });
}
const time24 = (dt && dt.isValid) ? dt.toFormat('HH:mm') : (pending.time || '09:00');
const date = parsed.date || pending.date;

return [{ json: {
  title: pending.title,
  date,
  time: time24,
  duration_minutes: pending.duration_minutes,
  description: pending.description,
  location_or_link: pending.location_or_link,
  chatId: pending.chatId
} }];

function getCandidate() {
  const names = ['Prepare Event Candidate', 'Build New Time Candidate', 'Prepare Replace Candidate'];
  for (const n of names) {
    try {
      const d = $(n).item.json;
      if (d && d.date) return d;
    } catch (e) {}
  }
  return {};
}

const candidate = getCandidate();
const tz = 'Asia/Dhaka';
const start = DateTime.fromFormat(`${candidate.date} ${candidate.time}`, 'yyyy-MM-dd HH:mm', { zone: tz });
const durationMin = Number(candidate.duration_minutes || 60);
const end = start.plus({ minutes: durationMin });

const events = $input.all();
let conflict = null;
for (const item of events) {
  const ev = item.json;
  if (!ev.start || !ev.start.dateTime || !ev.end || !ev.end.dateTime) continue;
  const evStart = DateTime.fromISO(ev.start.dateTime);
  const evEnd = DateTime.fromISO(ev.end.dateTime);
  if (start < evEnd && end > evStart) {
    conflict = { id: ev.id, title: ev.summary || '(No title)', start: evStart.toFormat('yyyy-MM-dd HH:mm'), end: evEnd.toFormat('yyyy-MM-dd HH:mm') };
    break;
  }
}

const refPayload = {
  title: candidate.title,
  date: candidate.date,
  time: candidate.time,
  duration_minutes: candidate.duration_minutes,
  description: candidate.description,
  location_or_link: candidate.location_or_link,
  conflictEventId: conflict ? conflict.id : ''
};
const auroraRef = Buffer.from(JSON.stringify(refPayload)).toString('base64');

return [{ json: {
  ...candidate,
  isConflict: !!conflict,
  conflictEventId: conflict ? conflict.id : '',
  conflictTitle: conflict ? conflict.title : '',
  conflictStart: conflict ? conflict.start : '',
  conflictEnd: conflict ? conflict.end : '',
  auroraRef
} }];

