const o = $json.output;
return [{ json: {
  entity: o.type,   // সরাসরি Aurora-র "type" field ব্যবহার করুন
  date: o.date,
  time: o.time,
  keyword: o.keyword,
  title: o.title,
  chatId: $('Telegram Trigger').item.json.message.chat.id
} }];

const req = $('Prepare Delete Request').item.json;
const events = $input.all().filter(e => e.json && e.json.id);
let matches = [];

if (req.date) {
  matches = events.filter(e => {
    const dt = e.json.start && (e.json.start.dateTime || e.json.start.date)
      ? DateTime.fromISO(e.json.start.dateTime || e.json.start.date).setZone('Asia/Dhaka').toFormat('yyyy-MM-dd')
      : null;
    return dt === req.date;
  });
} else if (req.time) {
  matches = events.filter(e => {
    const dt = e.json.start && e.json.start.dateTime
      ? DateTime.fromISO(e.json.start.dateTime).setZone('Asia/Dhaka').toFormat('HH:mm')
      : null;
    return dt === req.time;
  });
} else if (req.keyword) {
  const kw = req.keyword.toLowerCase();
  matches = events.filter(e => (e.json.summary || '').toLowerCase().includes(kw));
} else {
  matches = events;
}

return matches.map(e => ({
  json: {
    eventId: e.json.id,
    summary: e.json.summary || '(শিরোনামহীন)',
    startIso: (e.json.start && (e.json.start.dateTime || e.json.start.date)) || ''
  }
}));

const req = $('Prepare Delete Request').item.json;
const deleted = $('Filter Matching Events').all();
const count = deleted.length;
let text;
if (count === 0) {
  text = `🔍 ${req.date}${req.time ? ' ' + req.time : ''} সময়ে ম্যাচ করা কোনো মিটিং পাওয়া যায়নি, তাই কিছু delete করা হয়নি।`;
} else {
  const lines = deleted.map(e => {
    const t = e.json.startIso ? (e.json.startIso.length > 10 ? DateTime.fromISO(e.json.startIso).setZone('Asia/Dhaka').toFormat('HH:mm') : 'সারাদিন') : '';
    return `• ${e.json.summary}${t ? ' (' + t + ')' : ''}`;
  });
  text = `🗑️ <b>${count}টি মিটিং delete করা হয়েছে</b> (${req.date}):\n\n${lines.join('\n')}`;
}
return [{ json: { chatId: req.chatId, text } }];

const req = $('Prepare Delete Request').item.json;
const tasks = $input.all().filter(t => t.json && t.json.id);
let matches;
if (req.keyword) {
  const kw = req.keyword.toLowerCase();
  matches = tasks.filter(t => (t.json.title || '').toLowerCase().includes(kw));
} else {
  matches = tasks.filter(t => {
    if (!t.json.due) return false;
    const dueDate = DateTime.fromISO(t.json.due).setZone('Asia/Dhaka').toFormat('yyyy-MM-dd');
    return dueDate === req.date;
  });
}
return matches.map(t => ({ json: { taskId: t.json.id, title: t.json.title || '(শিরোনামহীন)' } }));

const req = $('Prepare Delete Request').item.json;
const deleted = $('Filter Matching Tasks').all();
const count = deleted.length;
let text;
if (count === 0) {
  text = `🔍 ${req.date} তারিখে ম্যাচ করা কোনো task পাওয়া যায়নি, তাই কিছু delete করা হয়নি।`;
} else {
  const lines = deleted.map(t => `• ${t.json.title}`);
  text = `🗑️ <b>${count}টি task delete করা হয়েছে</b> (${req.date}):\n\n${lines.join('\n')}`;
}
return [{ json: { chatId: req.chatId, text } }];

const req = $('Prepare Query Request').item.json;
const events = $('Get Events For Query').all().filter(e => e.json && e.json.id);
const allTasks = $('Get Tasks For Query').all().filter(t => t.json && t.json.id);
const dayTasks = allTasks.filter(t => {
  if (!t.json.due) return false;
  return DateTime.fromISO(t.json.due).setZone('Asia/Dhaka').toFormat('yyyy-MM-dd') === req.date;
});

let text = `🗓️ <b>${req.date}</b> তারিখের সময়সূচী:\n\n`;

if (req.entity !== 'task') {
  text += `📅 <b>Meetings (${events.length}):</b>\n`;
  if (events.length === 0) {
    text += 'কোনো মিটিং নেই।\n';
  } else {
    events.forEach(e => {
      const s = (e.json.start && e.json.start.dateTime) ? DateTime.fromISO(e.json.start.dateTime).setZone('Asia/Dhaka').toFormat('HH:mm') : 'সারাদিন';
      const en = (e.json.end && e.json.end.dateTime) ? DateTime.fromISO(e.json.end.dateTime).setZone('Asia/Dhaka').toFormat('HH:mm') : '';
      const attendees = (e.json.attendees || []).map(a => a.displayName || a.email).join(', ') || 'কোনো participant নেই';
      text += `\n• <b>${e.json.summary || '(শিরোনামহীন)'}</b>\n  🕒 ${s}${en ? ' - ' + en : ''}\n  👥 ${attendees}`;
      if (e.json.location) text += `\n  📍 ${e.json.location}`;
      text += '\n';
    });
  }
  text += '\n';
}

if (req.entity !== 'event') {
  text += `✅ <b>Tasks (${dayTasks.length}):</b>\n`;
  if (dayTasks.length === 0) {
    text += 'কোনো task নেই।\n';
  } else {
    dayTasks.forEach(t => {
      text += `\n• ${t.json.title}${t.json.notes ? ' — ' + t.json.notes : ''}\n`;
    });
  }
}

return [{ json: { chatId: req.chatId, text } }];

const items = $input.all();
const out = items.map(item => {
  const src = item.json.output || {};
  const o = { ...src };

  // Normalize time to strict 24-hour HH:mm (handles '10:00 AM', '10:00', '22:15', etc.)
  let t = String(o.time || '').trim();
  if (t) {
    let dt = DateTime.fromFormat(t, 'h:mm a', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'hh:mm a', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'H:mm', { zone: 'Asia/Dhaka' });
    if (!dt.isValid) dt = DateTime.fromFormat(t, 'HH:mm', { zone: 'Asia/Dhaka' });
    o.time = dt.isValid ? dt.toFormat('HH:mm') : '09:00';
  } else {
    o.time = o.type === 'event' ? '09:00' : '';
  }

  o.priority = String(o.priority || 'normal').toLowerCase();
  if (!o.duration_minutes || o.duration_minutes <= 0) o.duration_minutes = 60;

  return { json: { output: o } };
});
return out;
